"""Original neurocritical-care and coma chapter."""
from qbank_authoring import question,ref,finalize
ED=ref('Neurocritical Care Society Cerebral Edema Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC7272487/')
BT=ref('Brain Trauma Foundation Severe TBI Guideline, Fourth Edition','https://braintrauma.org/coma/guidelines/severe-tbi')
BD=ref('AAN/AAP/CNS/SCCM US BD/DNC Consensus Guideline, 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10791061/')
CA=ref('AHA Post–Cardiac Arrest Care Guideline, 2025','https://doi.org/10.1161/CIR.0000000000001375')
EN=ref('EAN/ESCMID Infectious Encephalitis Guideline, 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13650609/')
GC=ref('Merck Manual: Overview of Coma and Impaired Consciousness','https://www.merckmanuals.com/professional/neurologic-disorders/coma-and-impaired-consciousness/overview-of-coma-and-impaired-consciousness')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('An unresponsive patient arrives without a clear history. What is the best first principle?', 'Stabilize airway, breathing and circulation and rapidly check glucose while assessing reversible and structural causes',[
 ('Complete every localization test before supporting ventilation','Resuscitation cannot wait.'),('Assume intoxication without assessing glucose or trauma','Common reversible and dangerous causes can coexist.'),('Wait for imaging before treating profound hypoglycemia','Immediate correction is required.')],
 'Resuscitation and diagnosis proceed together', '**Coma threatens airway protection and may have immediately reversible causes.**', ['Check oxygenation, ventilation, circulation, glucose and temperature.','Obtain a collateral medication and exposure history.'], '**Use examination and imaging to refine the cause.**', ['Look for trauma, focal signs and seizures.','Do not let a suspected toxin delay structural evaluation when indicated.'], [['Immediate','ABC and glucose'],['Examination','Focal/brainstem/seizure clues'],['Cause','Structural, metabolic or toxic']], [GC], 'clinical_scenario')
q('Which pattern raises particular concern for a structural cause of coma?', 'Asymmetric motor responses with focal cranial-nerve or pupillary abnormalities',[
 ('Symmetry proves no structural disease can exist','Structural disease can sometimes be symmetric.'),('Any metabolic cause must have completely normal pupils','Toxins and metabolic states can alter pupils.'),('A normal initial CT excludes all brainstem disease','Imaging sensitivity and timing have limits.')],
 'Localization guides urgency without providing absolute rules', '**Asymmetry suggests focal injury, mass effect or a brainstem process.**', ['Seizure-related deficits can be a mimic.','Toxic-metabolic and structural problems may coexist.'], '**Arrange appropriate emergency imaging.**', ['Repeat the examination after stabilization.','Record confounders such as sedation or paralysis.'], [['Asymmetry','Structural concern'],['Symmetry','Often metabolic but not exclusive'],['Reassessment','Essential']], [GC])
q('Why should GCS components and confounders be documented rather than reporting only a total score?', 'Intubation, sedation, paralysis and focal deficits can make the same total reflect different clinical states',[
 ('The total alone uniquely identifies the cause of coma','It does not.'),('A verbal score is fully interpretable during endotracheal intubation','Intubation prevents ordinary verbal assessment.'),('A single score never needs repetition','Trend and context are important.')],
 'A numerical scale needs clinical context', '**Eye, verbal and motor components should be described separately.**', ['Record untestable elements and sedative exposure.','A unilateral deficit can alter motor interpretation.'], '**Follow the trajectory.**', ['A decline can signal urgent deterioration.','GCS is not a stand-alone brain-death or prognosis test.'], [['Components','Describe separately'],['Confounders','Document explicitly'],['Trend','Often more useful than one total']], [GC])
q('Pinpoint pupils and respiratory depression follow possible opioid exposure. What is an appropriate immediate strategy?', 'Support ventilation and give titrated naloxone when indicated while continuing the differential assessment',[
 ('Naloxone replaces airway and ventilation support','Respiratory support may still be required.'),('One response proves there is no coingestion or injury','Other causes may coexist.'),('Absence of pinpoint pupils excludes every opioid overdose','Pupil findings are not perfectly sensitive.')],
 'Treat the dangerous physiology first', '**The target of naloxone is reversal of clinically important opioid effect, particularly hypoventilation.**', ['Recurrent depression can occur with longer-acting opioids.','Withdrawal and agitation can follow excessive reversal.'], '**Monitor after initial improvement.**', ['Repeat dosing or infusion may be needed.','Assess coingestants, trauma and aspiration.'], [['Ventilation','Immediate support'],['Naloxone','Titrate to clinical need'],['Observation','Watch for recurrence']], [GC], 'clinical_scenario')
q('A malnourished comatose patient has severe hypoglycemia. What is the best treatment principle?', 'Give glucose immediately and provide prompt parenteral thiamine without delaying correction of hypoglycemia',[
 ('Withhold glucose until thiamine is available','This risks ongoing hypoglycemic brain injury.'),('Thiamine alone corrects the glucose emergency','It does not supply glucose.'),('A normal hemoglobin excludes thiamine deficiency','Nutritional neurological disease can occur without anemia.')],
 'Two urgent treatments can be coordinated', '**Hypoglycemia needs immediate correction.**', ['Thiamine is indicated when deficiency risk is present.','Give it before or alongside carbohydrate when feasible, but do not delay lifesaving glucose.'], '**Search for the cause and recurrence risk.**', ['Check insulin, sulfonylurea, liver and systemic contexts.','Monitor serial glucose after recovery.'], [['Glucose','Immediate'],['Thiamine','Prompt if at risk'],['Follow-up','Prevent recurrence']], [GC], 'clinical_scenario')
q('A deteriorating patient with an intracranial mass develops an ipsilateral dilated poorly reactive pupil. Which emergency is most concerning?', 'Uncal herniation with third-nerve compression',[
 ('A benign normal pupil variant as the default','New anisocoria during deterioration is an emergency.'),('Isolated peripheral neuropathy','This does not explain the intracranial deterioration.'),('An indication to perform LP before imaging','Mass effect makes LP potentially hazardous.')],
 'A new pupil change can indicate pressure-driven displacement', '**Uncal displacement can compress the ipsilateral oculomotor nerve.**', ['Motor and consciousness changes can accompany it.','Other ocular causes exist but must not delay emergency assessment.'], '**Initiate urgent pressure-directed and definitive care.**', ['Maintain oxygenation and perfusion and involve neurosurgery.','Use temporizing osmotherapy as indicated while addressing the cause.'], [['Pupil','Ipsilateral dilation'],['Mechanism','Third-nerve compression'],['Action','Emergency herniation care']], [ED,GC], 'clinical_scenario')
q('Hypertension, bradycardia and irregular respiration occur with worsening intracranial disease. What is the correct interpretation?', 'A concerning late pressure/herniation pattern rather than a sensitive early screening triad',[
 ('Its absence excludes dangerous raised ICP','Patients can deteriorate without the full triad.'),('It is required before treating herniation','Waiting can be fatal.'),('It proves a harmless vagal episode in every case','The intracranial context makes it concerning.')],
 'Do not wait for a late physiological sign', '**The Cushing response can indicate threatened brainstem function.**', ['Treat evolving clinical herniation based on the whole picture.','Individual components have other causes.'], '**Act before the full triad appears.**', ['Urgent stabilization, imaging and definitive treatment are needed.','Maintain cerebral perfusion while reducing the cause of pressure.'], [['Triad','Late concerning pattern'],['Absence','Does not exclude'],['Decision','Clinical deterioration drives urgency']], [ED,GC])
q('What is the standard bedside approximation of cerebral perfusion pressure when ICP is the relevant downstream pressure?', 'CPP = mean arterial pressure minus intracranial pressure',[
 ('CPP = systolic pressure plus ICP','This is not the relationship.'),('CPP = ICP minus heart rate','These quantities do not define CPP.'),('CPP equals oxygen saturation alone','Oxygenation and perfusion are different variables.')],
 'A pressure gradient drives perfusion', '**Rising ICP can reduce perfusion even when systemic pressure is unchanged.**', ['Hypotension can compound the problem.','Measurement level and clinical context affect interpretation.'], '**Treat the patient rather than a formula alone.**', ['Avoid both inadequate perfusion and harmful excessive pressure strategies.','Targets depend on the disease and monitoring context.'], [['MAP','Upstream pressure'],['ICP','Downstream constraint'],['CPP','Approximate gradient']], [BT])
q('What is a useful initial positioning principle in significant cerebral edema when not contraindicated?', 'Elevate the head appropriately and keep the neck midline while preserving perfusion and spinal safety',[
 ('Tight jugular compression to trap blood intracranially','This can worsen venous drainage.'),('Extreme elevation regardless of blood pressure','Excessive reduction of perfusion can be harmful.'),('Ignore spinal instability in a trauma patient','Positioning must respect injury precautions.')],
 'Venous drainage and perfusion must both be considered', '**Head elevation can reduce ICP through improved venous outflow.**', ['Avoid constrictive neck devices when possible.','Reassess systemic and cerebral pressure effects.'], '**Use it as part of a broader plan.**', ['Treat fever, agitation and the lesion causing edema.','Positioning does not replace definitive care.'], [['Head/neck','Support venous drainage'],['Perfusion','Monitor effect'],['Trauma','Maintain spinal precautions']], [ED])
q('Which treatments can provide temporizing ICP reduction in selected acute cerebral edema?', 'Hypertonic saline or mannitol with appropriate clinical and laboratory monitoring',[
 ('Either agent is a guaranteed long-term cure for the underlying lesion','They are temporizing therapies.'),('Osmotherapy needs no renal or electrolyte review','Toxicity monitoring is essential.'),('Routine prophylactic dosing is required in every headache','An appropriate clinical indication is needed.')],
 'Osmotherapy treats pressure physiology', '**Agent selection depends on the disease and patient’s sodium, volume and renal context.**', ['Mannitol can cause osmotic diuresis.','Hypertonic saline can affect sodium, chloride and volume.'], '**Reassess after each intervention.**', ['Monitor neurological response and relevant laboratory measures.','Arrange definitive treatment of the cause.'], [['Mannitol','Osmotic/diuretic effects'],['Hypertonic saline','Sodium/volume considerations'],['Both','Monitoring and cause-directed care']], [ED])
q('What is the appropriate role of acute hyperventilation during impending herniation?', 'A short temporizing bridge while definitive ICP treatment is arranged, rather than routine prolonged prophylaxis',[
 ('Prolonged profound hypocapnia is harmless in every brain injury','It can reduce cerebral blood flow and cause ischemia.'),('It permanently removes the mass lesion','It does not.'),('It is unnecessary to monitor ventilation after intubation','PaCO2 control matters.')],
 'Vasoconstriction lowers pressure at a perfusion cost', '**Hypocapnia can rapidly reduce cerebral blood volume.**', ['The effect is temporary.','Excessive or prolonged reduction can impair oxygen delivery.'], '**Use only in the proper emergency context.**', ['Pair with osmotherapy and definitive lesion management when indicated.','Return to an appropriate ventilatory target once stabilized.'], [['Benefit','Rapid temporary ICP effect'],['Risk','Reduced cerebral perfusion'],['Role','Bridge, not routine prolonged treatment']], [ED,BT])
q('Should corticosteroids be routinely used to improve outcome in severe traumatic brain injury?', 'No; they are not recommended and high-dose regimens have caused harm',[
 ('Yes, because they treat every cerebral edema mechanism equally','Edema mechanisms and evidence differ.'),('Yes, they replace neurosurgical management','They do not.'),('No, therefore steroids have no role in any neurological disorder','Other diseases such as selected tumor edema have different indications.')],
 'Do not generalize steroid benefit across edema types', '**Severe TBI is a setting where routine corticosteroid treatment is harmful rather than beneficial.**', ['Vasogenic tumor edema and selected inflammatory conditions have different evidence.','Diagnosis determines treatment.'], '**Use TBI-specific protocols.**', ['Maintain oxygenation, perfusion and appropriate ICP care.','Avoid importing another disease’s regimen.'], [['TBI','No routine steroid'],['Selected tumor edema','Different indication'],['Principle','Mechanism and evidence matter']], [BT])
q('Which ICP threshold does the Brain Trauma Foundation severe TBI guideline recommend treating?', 'ICP above 22 mmHg, interpreted with clinical and imaging findings',[
 ('Any value above zero regardless of context','Normal ICP is not zero.'),('Only after ICP reaches 60 mmHg','This would delay treatment dangerously.'),('A normal single reading excludes later deterioration','ICP is dynamic.')],
 'A treatment threshold belongs to a defined disease context', '**The BTF recommendation addresses monitored severe TBI.**', ['Waveform quality and examination matter.','Brief artifact differs from sustained pathological elevation.'], '**Integrate rather than treat the number blindly.**', ['Assess perfusion and the lesion.','Use a stepped plan appropriate to the patient.'], [['Context','Severe TBI'],['Threshold','Above 22 mmHg'],['Interpretation','Clinical/imaging integration']], [BT])
q('What CPP range is generally recommended in the BTF severe TBI guideline?', '60–70 mmHg, with individualization',[
 ('20–30 mmHg as a universal safe goal','This is generally inadequate for the recommended target.'),('Above 100 mmHg at any cost','Excessive pressure/volume strategies can cause harm.'),('No relationship exists between CPP and systemic pressure','MAP contributes directly to the gradient.')],
 'Balance perfusion against treatment burden', '**BTF recommends a target range of 60–70 mmHg.**', ['Autoregulation and patient factors can influence the best target.','Avoid aggressive excessive CPP strategies that create systemic complications.'], '**Monitor the response.**', ['Treat hypotension and raised ICP in a coordinated way.','Do not extrapolate a severe-TBI range to every neurological disease unchanged.'], [['CPP','60–70 mmHg'],['Individualization','Autoregulation/context'],['Avoid','Harmful overcorrection']], [BT])
q('A critically ill patient remains unexpectedly unresponsive after convulsive movements stop. Which investigation is particularly important?', 'EEG, often continuous monitoring when indicated, to assess ongoing nonconvulsive seizures',[
 ('No further seizure assessment because movement has stopped','Electrical seizures can persist without obvious motor activity.'),('A routine oxygen reading as a substitute for EEG','It does not assess cortical electrical activity.'),('Immediate irreversible prognosis from the bedside appearance alone','Sedation, seizures and metabolic causes can confound the examination.')],
 'Motor silence is not equivalent to electrical seizure cessation', '**Nonconvulsive seizures can contribute to impaired awareness.**', ['Sedative and postictal effects are competing explanations.','EEG interpretation must fit the clinical context.'], '**Treat confirmed disease and the cause.**', ['Use a specialist seizure protocol.','Reassess consciousness after confounders and seizures are addressed.'], [['Movement stopped','Does not prove electrical cessation'],['EEG','Detects occult seizures'],['Coma assessment','Multiple confounders']], [EN,GC], 'clinical_scenario')
q('What is a sound temperature-management principle in a comatose adult after cardiac arrest?', 'Use protocolized temperature control and fever prevention rather than leaving temperature unmanaged',[
 ('Any single temperature guarantees recovery','No isolated target guarantees outcome.'),('Temperature management replaces ventilation and hemodynamic care','Post-arrest care is multimodal.'),('Fever is always beneficial after hypoxic brain injury','Uncontrolled fever is not the recommended strategy.')],
 'Secondary brain injury is partly preventable', '**Temperature control is part of post-arrest care.**', ['Target and duration follow current guidance and the clinical setting.','Shivering and sedation can complicate management.'], '**Coordinate the whole resuscitation plan.**', ['Address oxygenation, ventilation, circulation and seizures.','Avoid premature prognosis during treatment.'], [['Temperature','Protocolized control'],['Fever','Prevent/treat'],['Care','Multimodal']], [CA])
q('When should final multimodal neurological prognostic interpretation generally be consolidated after cardiac arrest under AHA 2025 guidance?', 'At least 72 hours after normothermia and discontinuation of sedatives, with confounders addressed',[
 ('Immediately after ROSC from one motor examination','Early findings are confounded and can be unreliable.'),('At any time from one biomarker alone','A single test is not sufficient.'),('Never, because prognosis is always impossible','Careful delayed multimodal assessment is appropriate.')],
 'Timing reduces false pessimistic predictions', '**Sedation, hypothermia and systemic illness can delay awakening.**', ['Use examination, electrophysiology, imaging and selected biomarkers together.','The observation period may need extension when uncertainty remains.'], '**Communicate uncertainty clearly.**', ['Do not use coma duration alone as proof of irreversible injury.','Separate prognosis from the patient’s values and treatment preferences.'], [['Timing','After normothermia/sedative clearance'],['Method','Multimodal'],['Uncertainty','May require more observation']], [CA])
q('What must be established before a formal US 2023 brain-death/death-by-neurologic-criteria evaluation?', 'A known catastrophic permanent brain injury with prerequisites met and relevant confounders excluded',[
 ('Any low GCS alone','Coma severity alone does not establish BD/DNC.'),('A sedative overdose with unknown clearance as proof','Drug effects must be excluded appropriately.'),('An isolated flat EEG as a universal substitute','The US 2023 guideline does not accept EEG as an ancillary BD/DNC test.')],
 'Death determination has stricter requirements than prognosis', '**Temperature, blood pressure, drug effects and metabolic confounders require explicit assessment.**', ['Clinical examination and apnea testing follow a defined protocol.','Applicable law and institutional requirements also govern the process.'], '**Do not bypass prerequisites.**', ['Ancillary tests are used only in specified circumstances.','This US framework is not an automatic replacement for another jurisdiction’s rules.'], [['Cause','Known permanent catastrophic injury'],['Prerequisites','Must be met'],['Jurisdiction','Follow governing requirements']], [BD])
q('Which combination forms the core clinical basis for BD/DNC in the US 2023 consensus framework after prerequisites are satisfied?', 'Coma, absence of required brainstem reflexes and apnea demonstrated by a valid protocol-based test',[
 ('Inability to walk while awake','This is not a death criterion.'),('A single abnormal pupil with preserved brain-mediated activity','This does not meet the required examination.'),('A poor predicted outcome without testing','Prognosis and death determination are different.')],
 'The examination tests brain-mediated functions', '**All required elements must be assessed according to the protocol.**', ['Spinal reflex movements can occur and need expert interpretation.','Any evidence of brain-mediated activity prevents the determination.'], '**Use qualified examiners and documentation.**', ['Apnea testing requires physiological preparation and safety limits.','Do not improvise a simplified bedside test.'], [['Coma','No arousal/awareness'],['Brainstem','Required reflexes absent'],['Respiration','Valid apnea test']], [BD])
q('Which statement about ancillary testing follows the US 2023 BD/DNC guideline?', 'It is reserved for defined limitations of the examination or apnea test; EEG is not an accepted ancillary test in that framework',[
 ('A flat EEG independently replaces every prerequisite','It does not assess all brainstem functions and is not accepted here.'),('Ancillary testing can overrule definite brain-mediated activity','It must not be used to make that contradiction disappear.'),('Every imaging technique is interchangeable and fully validated','Acceptable modalities are specifically defined.')],
 'An ancillary test answers a restricted question', '**The guideline specifies appropriate cerebral-perfusion methods and circumstances.**', ['Adult transcranial Doppler has a defined role; pediatric rules differ.','CT angiography is not an accepted modality under this US consensus framework.'], '**Follow jurisdiction-specific requirements.**', ['Other countries may use different authorized methods.','Never use a test to avoid unresolved sedative or temperature confounders.'], [['Indication','Specified incomplete assessment'],['EEG','Not accepted in US 2023 framework'],['Rules','Modality- and jurisdiction-specific']], [BD])
q('A conscious patient is quadriplegic and anarthric but follows commands with vertical eye movements. Which syndrome is most likely?', 'Locked-in syndrome',[
 ('Coma','Awareness is preserved.'),('Unresponsive wakefulness syndrome','Command-following demonstrates awareness.'),('Brain death','Brain-mediated eye responses and consciousness exclude it.')],
 'Motor output and awareness can dissociate', '**Ventral pontine injury can interrupt motor pathways while sparing consciousness.**', ['Vertical gaze or blinking may provide communication.','Not every patient has the identical preserved movement pattern.'], '**Test communication deliberately.**', ['Avoid assuming unresponsiveness from absent limb movement.','Provide assistive communication and urgent etiological care.'], [['Awareness','Preserved'],['Motor output','Severely impaired'],['Communication','Eye movement/blinking']], [GC], 'clinical_scenario')
q('What best distinguishes minimally conscious state from unresponsive wakefulness syndrome?', 'Definite but sometimes inconsistent behavioral evidence of awareness',[
 ('Eye opening alone proves full awareness','Wakefulness and awareness differ.'),('A single reflex withdrawal always proves command comprehension','Reflex and purposeful behavior need distinction.'),('The diagnosis can be made without repeated examination or confounder review','Assessment can fluctuate and requires expertise.')],
 'Arousal and awareness are separate dimensions', '**Minimally conscious patients show reproducible or clearly discernible evidence of awareness.**', ['Language, motor and sensory deficits can obscure responses.','Sedation and seizures can confound assessment.'], '**Use repeated standardized evaluation.**', ['Optimize communication opportunities and medical conditions.','Avoid an irreversible label from one brief observation.'], [['Wakefulness','Eye-opening/arousal'],['Awareness','Purposeful evidence'],['Assessment','Repeated and standardized']], [GC])
q('Acute neurological deterioration occurs in a patient with severe brain disease. What is the best transport-to-imaging principle?', 'Stabilize airway, ventilation and circulation sufficiently and maintain monitoring during urgent imaging',[
 ('Send an unstable unmonitored patient immediately without support','Transport can precipitate avoidable harm.'),('Defer every scan indefinitely because the patient is critical','Urgent imaging may be essential to definitive treatment.'),('Stop all critical infusions for transport convenience','Necessary support must continue safely.')],
 'The trip to the scanner is part of critical care', '**Oxygenation, perfusion and equipment continuity matter during transport.**', ['Communicate the neurological and airway risks.','An appropriately skilled team should accompany the patient.'], '**Balance stabilization with urgency.**', ['Do not create avoidable delay for a time-critical lesion.','Reassess the examination and vital signs after movement.'], [['Before','Essential stabilization'],['During','Monitoring and support'],['After','Clinical reassessment']], [GC,ED], 'clinical_scenario')
q('Why should profound sedation or neuromuscular blockade be explicitly considered in a comatose patient’s neurological assessment?', 'They can suppress observable responses and invalidate conclusions drawn from an apparently absent examination',[
 ('Paralysis always removes consciousness','Neuromuscular blockers do not themselves provide sedation or analgesia.'),('A missing motor response under blockade proves irreversible injury','It can be pharmacological.'),('Drug clearance is identical in every critically ill patient','Organ dysfunction and exposure duration can prolong effects.')],
 'An unobservable response may reflect the treatment', '**Sedation affects arousal; paralysis affects motor expression.**', ['Temperature, organ function and accumulated drug alter clearance.','Adequate sedation is still necessary during paralysis.'], '**Document and reassess appropriately.**', ['Use drug history and protocol-based clearance assessment.','Do not confuse treatment-induced silence with absence of brain function.'], [['Sedative','Arousal confounder'],['Blocker','Motor-output confounder'],['Clearance','Patient-specific']], [GC,BD])

if __name__=='__main__':finalize('Neurology',15,'Neurocritical Care and Coma','neuro-neurocritical',rows,24)
